export function solve(rows, key) {
  let best = null;
  for (const row of rows) if (best === null || row[key] > best[key]) best = row;
  return best;
}

referenceSolutions.typescript:
export function solve(rows: Record<string, any>[], key: string): any {
  let best: Record<string, any> | null = null;
  for (const row of rows) if (best === null || row[key] > best[key]) best = row;
  return best;
}
